import datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
SUF = {'lirası': "'dır", 'kuruş': "'tur", 'dolar': "'dır", 'euro': "'dur", 'sterlini': "'dir", 'sent': "'tir", 'peni': "'dir"}

def w3(n):
    h, t, o = n // 100, (n // 10) % 10, n % 10
    p = []
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for size, lab in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        g = n // size
        n = n % size
        if g:
            out.append('bin' if (lab == 'bin' and g == 1) else w3(g) + ' ' + lab)
    if n:
        out.append(w3(n))
    return ' '.join(out)

def amount(v, cur):
    v = round(abs(float(v)), 2)
    whole = int(v)
    frac = int(round((v - whole) * 100))
    if cur == 'TL':
        return words(whole) + (' lira ' + words(frac) + ' kuruş' if frac else ' Türk Lirası')
    nm = {'USD': 'Dolar', 'EUR': 'Euro', 'GBP': 'İngiliz Sterlini'}[cur]
    sub = 'peni' if cur == 'GBP' else 'sent'
    return words(whole) + ' ' + nm + (' ' + words(frac) + ' ' + sub if frac else '')

def cop(text):
    return text + SUF.get(text.split()[-1].lower(), "'dir")

def pdate(s):
    try:
        return datetime.datetime.strptime(str(s).strip()[:10], '%d.%m.%Y').date()
    except Exception:
        return None

def sdate(d):
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)

def date_cop(d):
    y = d.year
    o, t = y % 10, (y // 10) % 10
    if o:
        s = {1: "'dir", 2: "'dir", 3: "'tür", 4: "'tür", 5: "'tir", 6: "'dır", 7: "'dir", 8: "'dir", 9: "'dur"}[o]
    elif t:
        s = {1: "'dur", 2: "'dir", 3: "'dur", 4: "'tır", 5: "'dir", 6: "'tır", 7: "'tir", 8: "'dir", 9: "'dır"}[t]
    else:
        s = "'dür" if (y // 100) % 10 else "'dir"
    return sdate(d) + s

def f(b, k):
    try:
        return float(b.get(k) or 0)
    except Exception:
        return 0.0

